from collections import deque

def components(grid, top_end, bg):
  seen=set(); comps=[]
  for r in range(top_end):
    for c in range(24):
      v=grid[r][c]
      if v==bg or (r,c) in seen: continue
      q=deque([(r,c)]); seen.add((r,c)); pts=[]
      while q:
        y,x=q.popleft(); pts.append((y,x))
        for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
          yy,xx=y+dy,x+dx
          if 0<=yy<top_end and 0<=xx<24 and (yy,xx) not in seen and grid[yy][xx]==v:
            seen.add((yy,xx)); q.append((yy,xx))
      comps.append((v,pts))
  return comps

def predict(demo, panels, bg):
  a,b=demo
  p=[row[:] for row in a]
  top_end=min(s for s,e,bd,fi in panels)
  cs=components(a,top_end,bg)
  for col,pts in cs:
    ys=[y for y,x in pts]; xs=[x for y,x in pts]
    y0,y1=min(ys),max(ys); x0,x1=min(xs),max(xs)
    for s,e,bd,fi in panels:
      if fi!=col: continue
      dy=e-(y1-y0+1)+1-y0
      for y,x in pts:
        yy=y+dy
        p[yy][x]=bd
  return p,cs
